const { answers } = await env.AI.run("@cf/cloudflare/clairic", {
  state: email,
  fields: {
    order_id:     { type: "text", instructions: "Order number" },
    delivered_on: { type: "date", instructions: "Delivery date" },
    amount_paid:  { type: "number", decimals: 2, unit: "USD",
                    instructions: "Total paid including tax" },
    damage:       { type: "list", items: "text",
                    instructions: "Each kind of damage described" },
  },
});

response = bedrock_runtime.invoke_model(
    modelId="global.anthropic.claude-sonnet-5-5",
    body=json.dumps({
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": 512,
        "messages": [{"role": "user", "content": text}],
        "output_config": {"format": {"type": "json_schema", "schema": schema}},
    }),
)
body = json.loads(response["body"].read())
if body["stop_reason"] == "end_turn":
    result = json.loads(next(b["text"] for b in body["content"] if b["type"] == "text"))
